// ============ Administration ============
const ADMIN_SECTIONS = [['overview', 'Overview'], ['users', 'Users'], ['roles', 'Roles & Permissions'], ['departments', 'Departments'], ['workflows', 'Workflow Configuration'], ['templates', 'Memo Templates'], ['notifications', 'Notification Templates'], ['configuration', 'Configuration'], ['audit', 'Audit Logs'], ['settings', 'System Settings'], ['backup', 'Backup & Recovery'], ['archive', 'Archive & Records']];
const UF = { q: '', dept: '', role: '', status: '' };
const AF = { q: '', module: '', user: '', from: '', to: '' };

function storageSize() { let b = 0; try { b = (localStorage.getItem(DB_KEY) || '').length * 2; } catch (e) { } return b; }

PAGES.admin = (ctx) => {
  const sec = ctx.parts[1] || 'overview';
  const allowed = { users: 'admin.users', roles: 'admin.users', departments: 'admin.users', audit: 'admin.audit', backup: 'admin.backup' }[sec] || 'admin.config';
  const label = ADMIN_SECTIONS.find(s => s[0] === sec)?.[1] || 'Overview';
  if (!can(allowed)) { ctx.el.innerHTML = `<div class="card card-pad empty">${icon('lock')}<p>You do not have permission to access this page.</p></div>`; return { title: label }; }
  const fn = ADMIN[sec] || ADMIN.overview;
  fn(ctx.el);
  return { title: sec === 'overview' ? 'Administration Overview' : label, crumbs: [['Home', '#/dashboard'], ['Administration', '#/admin/overview'], [label]] };
};
const ADMIN = {};

ADMIN.overview = (el) => {
  const days = []; for (let i = 29; i >= 0; i--) { const d = new Date(); d.setDate(d.getDate() - i); days.push(d); }
  const logins = days.map(d => DB.audit.filter(a => a.action === 'User Login' && new Date(a.date).toDateString() === d.toDateString()).length);
  const acts = days.map(d => DB.audit.filter(a => a.module !== 'Authentication' && new Date(a.date).toDateString() === d.toDateString()).length);
  const sz = storageSize(); const files = DB.memos.reduce((a, m) => a + m.attachments.filter(x => !x.demo).reduce((s, x) => s + x.size, 0), 0);
  const actIcon = { 'User Login': ['user', 'bg-green'], 'Memo Released': ['send', 'bg-blue'], 'User Created': ['users', 'bg-purple'], 'Role Updated': ['shield', 'bg-orange'], 'Backup Completed': ['database', 'bg-green'] };
  el.innerHTML = `<div class="grid g5 mb">${statCard('blue', 'users', 'Total Users', DB.users.length, DB.users.filter(u => u.status === 'Active').length + ' active')}${statCard('green', 'shield', 'User Roles', DB.roles.length, 'Defined roles')}${statCard('orange', 'building', 'Departments', DB.departments.length, 'Active departments')}${statCard('purple', 'workflow', 'Workflows', DB.workflows.length, 'Approval workflows')}${statCard('teal', 'database', 'Database Size', fmtSize(sz), 'Stored in this browser')}</div>
  <div class="grid" style="grid-template-columns:minmax(0,1.5fr) minmax(0,1fr) minmax(0,1fr)">
    <div class="card card-pad"><div class="card-h"><h3>User Activity (Last 30 Days)</h3></div>${lineChart(days.map(d => MONTHS[d.getMonth()] + ' ' + d.getDate()), [{ label: 'Logins', data: logins, color: '#1d4ed8' }, { label: 'Other Actions', data: acts, color: '#16a34a' }], { h: 220 })}<div class="row" style="justify-content:space-around;text-align:center;margin-top:10px"><div><div class="small t2">Total Logins</div><b style="font-size:20px;color:var(--primary)">${logins.reduce((a, b) => a + b, 0)}</b></div><div><div class="small t2">Actions</div><b style="font-size:20px" class="green">${acts.reduce((a, b) => a + b, 0)}</b></div><div><div class="small t2">Inactive Users</div><b style="font-size:20px" class="red">${DB.users.filter(u => u.status !== 'Active').length}</b></div></div></div>
    <div class="card card-pad"><div class="card-h"><h3>System Status</h3></div><div style="text-align:center;color:var(--green)">${icon('checkc').replace('width="18" height="18"', 'width="60" height="60"')}<h3 style="color:var(--text);margin-top:6px">All Systems Operational</h3><div class="small t2">No issues detected</div></div>${[['Web Application', 'Operational'], ['Data Storage (Browser)', 'Operational'], ['File Storage (IndexedDB)', typeof indexedDB !== 'undefined' ? 'Operational' : 'Unavailable'], ['Email Service', DB.settings.emailEnabled ? 'Simulated' : 'Disabled'], ['Backup Service', 'Manual']].map(([a, b]) => `<div class="row small" style="padding:7px 0;border-bottom:1px solid var(--border-2)"><span class="green">${icon('checkc')}</span>${a}<span class="spacer"></span><span class="green">${b}</span></div>`).join('')}<div class="xs t2 mt">Last checked: ${fmtDT(NOW())}</div></div>
    <div class="card card-pad"><div class="card-h"><h3>Storage Usage</h3></div><div class="row" style="gap:12px;flex-wrap:wrap">${donut([{ label: 'Memo Data', value: sz, color: '#1d4ed8' }, { label: 'Attachments', value: files, color: '#16a34a' }], { size: 150, center: fmtSize(sz + files), sub: 'Total' })}${legendList([{ label: 'Memo Data', value: Math.round(sz / 1024), color: '#1d4ed8' }, { label: 'Attachments', value: Math.round(files / 1024), color: '#16a34a' }])}</div><div class="xs t2 mt">Values in KB.</div><a class="btn mt" href="#/admin/backup">${icon('folder')} Backup & Recovery</a></div>
  </div>
  <div class="grid mt" style="grid-template-columns:minmax(0,2fr) minmax(0,1fr)">
    <div class="card"><div class="card-pad" style="padding-bottom:6px"><h3>Recent System Activities</h3></div><table class="tbl"><thead><tr><th>Activity</th><th>Details</th><th>User</th><th>Date & Time</th></tr></thead><tbody>${DB.audit.slice(0, 7).map(a => { const [ic, c] = actIcon[a.action] || ['activity', 'bg-blue']; return `<tr><td><span class="row"><span class="qa-i" style="padding:0;border:0"><span class="ic ${c}" style="width:28px;height:28px;flex-basis:28px">${icon(ic)}</span></span>${esc(a.action)}</span></td><td class="small">${esc(a.details)}</td><td>${esc(userById(a.userId).name)}</td><td>${fmtDT(a.date)}</td></tr>`; }).join('')}</tbody></table><div style="text-align:center;padding:12px"><a href="#/admin/audit">View All Activity Logs</a></div></div>
    <div class="card card-pad"><div class="card-h"><h3>Quick Actions</h3></div>${[['user', 'Add New User', 'Create a new user account', 'users?new=1'], ['shield', 'Create New Role', 'Create a new user role', 'roles?new=1'], ['database', 'System Backup', 'Download a full backup', 'backup'], ['workflow', 'Workflow Configuration', 'Manage approval routes', 'workflows'], ['shieldc', 'Audit Logs', 'Review all system activity', 'audit']].map(([i, t, s, h]) => `<a class="file-row" style="text-decoration:none;color:inherit" href="#/admin/${h}"><span style="color:var(--primary)">${icon(i)}</span><div style="flex:1"><b class="small">${t}</b><div class="xs t2">${s}</div></div>${icon('arrowr')}</a>`).join('')}</div>
  </div>`;
};

// ----- Users -----
function userForm(u) {
  formModal({ title: u ? 'Edit User' : 'Add New User', wide: true, fields: [
    { name: 'name', label: 'Full Name', required: true, value: u?.name }, { name: 'email', label: 'Email', type: 'email', required: true, value: u?.email },
    { name: 'deptId', label: 'Department', type: 'select', options: DB.departments.map(d => [d.id, d.name]), value: u?.deptId }, { name: 'title', label: 'Position / Title', required: true, value: u?.title },
    { name: 'roleId', label: 'Role', type: 'select', options: DB.roles.map(r => [r.id, r.name]), value: u?.roleId || 'r-employee' }, { name: 'status', label: 'Status', type: 'select', options: ['Active', 'Inactive', 'Locked'], value: u?.status || 'Active' }],
    onSave: v => {
      if (!/^\S+@\S+\.\S+$/.test(v.email)) { toast('Please enter a valid email.', true); return false; }
      if (DB.users.some(x => x.email.toLowerCase() === v.email.toLowerCase() && x.id !== u?.id)) { toast('Email already in use.', true); return false; }
      if (u) { if (u.id === DB.currentUserId && v.roleId !== u.roleId && !roleById(v.roleId).perms.includes('admin.users')) { toast('You cannot remove your own admin access.', true); return false; } Object.assign(u, v); audit('Users', 'User Updated', `User ${v.name} was updated.`); }
      else { DB.users.push({ id: uid('u'), ...v, createdAt: iso(NOW()), lastLogin: null }); audit('Users', 'User Created', `New user ${v.name} was created.`); }
      saveDB(); toast('User saved.'); rerender();
    } });
}
ADMIN.users = (el) => {
  if (CUR.query.new) { setTimeout(() => userForm(), 50); history.replaceState(null, '', '#/admin/users'); }
  const q = UF.q.toLowerCase();
  const rows = DB.users.filter(u => (!q || `${u.name} ${u.email} ${deptById(u.deptId).name}`.toLowerCase().includes(q)) && (!UF.dept || u.deptId === UF.dept) && (!UF.role || u.roleId === UF.role) && (!UF.status || u.status === UF.status));
  const monthStart = new Date(); monthStart.setDate(1);
  const t = dataTable({ id: 'users', rows, columns: [
    { key: 'name', label: 'User', render: u => `<span class="row">${avatar(u, 'sm')}<b class="small">${esc(u.name)}</b>${u.id === DB.currentUserId ? badge('You', 'b-blue') : ''}</span>` },
    { key: 'email', label: 'Email' }, { key: 'dept', label: 'Department', render: u => esc(deptById(u.deptId).name), sortVal: u => deptById(u.deptId).name },
    { key: 'title', label: 'Position' }, { key: 'role', label: 'Role', render: u => esc(roleById(u.roleId).name), sortVal: u => roleById(u.roleId).name },
    { key: 'status', label: 'Status', render: u => badge(u.status) }, { key: 'lastLogin', label: 'Last Login', render: u => u.lastLogin ? fmtDT(u.lastLogin) : '<span class="t2">Never</span>' },
    { key: 'createdAt', label: 'Date Created', render: u => fmtDate(u.createdAt) },
    { label: 'Actions', render: u => `<span class="row" style="gap:2px"><button class="icon-btn" data-ue="${u.id}">${icon('edit')}</button><button class="icon-btn" title="${u.status === 'Locked' ? 'Unlock' : 'Lock'}" data-ul="${u.id}">${icon(u.status === 'Locked' ? 'unlock' : 'lock')}</button><button class="icon-btn" data-um="${u.id}">${icon('dots')}</button></span>` }] });
  el.innerHTML = `<div class="row mb" style="justify-content:flex-end"><button class="btn" id="imp">${icon('upload')} Import Users (CSV)</button><button class="btn" id="expu">${icon('download')} Export</button><button class="btn primary" id="addu">${icon('plus')} Add New User</button><input type="file" id="imp-f" accept=".csv" hidden></div>
  <div class="grid g5 mb">${statCard('blue', 'users', 'Total Users', DB.users.length, 'Users in the system')}${statCard('green', 'checkc', 'Active Users', DB.users.filter(u => u.status === 'Active').length, pct(DB.users.filter(u => u.status === 'Active').length, DB.users.length) + ' of total users')}${statCard('orange', 'xc', 'Inactive Users', DB.users.filter(u => u.status === 'Inactive').length, pct(DB.users.filter(u => u.status === 'Inactive').length, DB.users.length) + ' of total users')}${statCard('purple', 'lock', 'Locked Users', DB.users.filter(u => u.status === 'Locked').length, pct(DB.users.filter(u => u.status === 'Locked').length, DB.users.length) + ' of total users')}${statCard('teal', 'plus', 'New This Month', DB.users.filter(u => new Date(u.createdAt) >= monthStart).length, 'Users added this month')}</div>
  <div class="card"><div class="filters"><div class="field search"><input class="inp" id="u-q" placeholder="Search users by name, email, or department..." value="${esc(UF.q)}">${icon('search')}</div>
  <div class="field"><label>Department</label><select class="inp" id="u-dept">${selectOpts(DB.departments.map(d => [d.id, d.name]), UF.dept, 'All Departments')}</select></div><div class="field"><label>Role</label><select class="inp" id="u-role">${selectOpts(DB.roles.map(r => [r.id, r.name]), UF.role, 'All Roles')}</select></div><div class="field"><label>Status</label><select class="inp" id="u-status">${selectOpts(['Active', 'Inactive', 'Locked'], UF.status, 'All Statuses')}</select></div><button class="btn" id="u-reset">${icon('reset')} Reset</button></div>${t.html}</div>`;
  t.mount(el, rerender);
  let tm; $('#u-q', el).oninput = e => { clearTimeout(tm); tm = setTimeout(() => { UF.q = e.target.value; rerender(); const n = $('#u-q'); n.focus(); n.setSelectionRange(n.value.length, n.value.length); }, 300); };
  ['dept', 'role', 'status'].forEach(k => $('#u-' + k, el).onchange = e => { UF[k] = e.target.value; rerender(); });
  $('#u-reset', el).onclick = () => { Object.assign(UF, { q: '', dept: '', role: '', status: '' }); rerender(); };
  $('#addu', el).onclick = () => userForm();
  $('#expu', el).onclick = () => exportCSV('users.csv', ['Name', 'Email', 'Department', 'Position', 'Role', 'Status', 'Last Login'], rows.map(u => [u.name, u.email, deptById(u.deptId).name, u.title, roleById(u.roleId).name, u.status, fmtDT(u.lastLogin)]));
  $('#imp', el).onclick = () => modal({ title: 'Import Users', body: `<div class="info">${icon('info')}<div>Upload a CSV file with columns: <b>Name, Email, Department Code, Position, Role</b>. Example:<br><code>Ana Reyes,ana.reyes@leonio.com,HR,HR Assistant,Employee</code></div></div>`, foot: `<button class="btn" data-x>Cancel</button><button class="btn primary" id="pick-csv">${icon('upload')} Choose CSV File</button>`, onMount: (m, close) => $('#pick-csv', m).onclick = () => { close(); $('#imp-f', el).click(); } });
  $('#imp-f', el).onchange = async e => { const f = e.target.files[0]; if (!f) return; const lines = (await f.text()).split(/\r?\n/).filter(l => l.trim()); let n = 0, skip = 0; lines.forEach((l, i) => { const c = l.split(',').map(x => x.trim().replace(/^"|"$/g, '')); if (i === 0 && /name/i.test(c[0])) return; if (!c[0] || !c[1] || DB.users.some(u => u.email.toLowerCase() === c[1].toLowerCase())) { skip++; return; } const d = DB.departments.find(x => x.code.toLowerCase() === (c[2] || '').toLowerCase() || x.name.toLowerCase() === (c[2] || '').toLowerCase()); const r = DB.roles.find(x => x.name.toLowerCase() === (c[4] || '').toLowerCase()); DB.users.push({ id: uid('u'), name: c[0], email: c[1], deptId: d?.id || DB.departments[0].id, title: c[3] || 'Employee', roleId: r?.id || 'r-employee', status: 'Active', createdAt: iso(NOW()), lastLogin: null }); n++; }); audit('Users', 'Users Imported', `${n} user(s) imported from ${f.name}.`); saveDB(); toast(`${n} user(s) imported${skip ? `, ${skip} skipped` : ''}.`); rerender(); };
  $$('[data-ue]', el).forEach(b => b.onclick = () => userForm(DB.users.find(u => u.id === b.dataset.ue)));
  $$('[data-ul]', el).forEach(b => b.onclick = () => { const u = DB.users.find(x => x.id === b.dataset.ul); if (u.id === DB.currentUserId) { toast('You cannot lock your own account.', true); return; } u.status = u.status === 'Locked' ? 'Active' : 'Locked'; audit('Users', u.status === 'Locked' ? 'User Locked' : 'User Unlocked', `User ${u.name} ${u.status === 'Locked' ? 'locked' : 'unlocked'}.`); saveDB(); toast(`${u.name} ${u.status === 'Locked' ? 'locked' : 'unlocked'}.`); rerender(); });
  $$('[data-um]', el).forEach(b => b.onclick = () => { const u = DB.users.find(x => x.id === b.dataset.um); popMenu(b, [{ label: 'Reset Password', icon: 'key', onClick: () => { audit('Users', 'Password Reset', `Password reset link sent to ${u.email}.`); saveDB(); toast('Password reset link sent to ' + u.email + ' (simulated).'); } }, { label: u.status === 'Inactive' ? 'Activate' : 'Deactivate', icon: 'refresh', onClick: () => { if (u.id === DB.currentUserId) { toast('You cannot deactivate yourself.', true); return; } u.status = u.status === 'Inactive' ? 'Active' : 'Inactive'; audit('Users', 'User Status Changed', `User ${u.name} set to ${u.status}.`); saveDB(); rerender(); } }, { label: 'View Activity', icon: 'activity', onClick: () => { AF.user = u.id; location.hash = '#/admin/audit'; } }]); });
};

// ----- Roles -----
ADMIN.roles = (el) => {
  const editRole = (r) => formModal({ title: r ? 'Edit Role' : 'Create New Role', fields: [{ name: 'name', label: 'Role Name', required: true, value: r?.name }, { name: 'description', label: 'Description', type: 'textarea', rows: 2, value: r?.description }, ...(!r ? [{ name: 'copy', label: 'Copy permissions from', type: 'select', options: [['', '— None —'], ...DB.roles.map(x => [x.id, x.name])] }] : [])], onSave: v => { if (r) Object.assign(r, { name: v.name, description: v.description }); else DB.roles.push({ id: uid('r'), name: v.name, description: v.description, perms: v.copy ? [...roleById(v.copy).perms] : ['memo.view'] }); audit('Roles', r ? 'Role Updated' : 'Role Created', `Role '${v.name}' ${r ? 'updated' : 'created'}.`); saveDB(); toast('Role saved.'); rerender(); } });
  if (CUR.query.new) { setTimeout(() => editRole(), 50); history.replaceState(null, '', '#/admin/roles'); }
  el.innerHTML = `<div class="row mb" style="justify-content:flex-end"><button class="btn primary" id="addr">${icon('plus')} Create New Role</button></div>
  <div class="grid g3 mb">${DB.roles.map(r => `<div class="card card-pad"><div class="row"><span class="cat-ic" style="background:var(--primary)">${icon('shield')}</span><div style="flex:1"><b>${esc(r.name)}</b><div class="xs t2">${DB.users.filter(u => u.roleId === r.id).length} user(s) · ${r.perms.length} permissions</div></div><button class="icon-btn" data-re="${r.id}">${icon('edit')}</button>${r.id !== 'r-admin' ? `<button class="icon-btn" data-rd="${r.id}">${icon('trash')}</button>` : ''}</div><div class="small t2" style="margin-top:10px">${esc(r.description)}</div></div>`).join('')}</div>
  <div class="card"><div class="card-pad" style="padding-bottom:6px"><h3>Permission Matrix</h3><div class="small t2" style="margin-top:4px">Tick a box to grant a permission to a role. Changes are saved immediately.</div></div><div class="tbl-wrap"><table class="tbl perm-tbl"><thead><tr><th>Permission</th>${DB.roles.map(r => `<th>${esc(r.name)}</th>`).join('')}</tr></thead><tbody>${PERMISSIONS.map(([k, l]) => `<tr><td>${esc(l)}<div class="xs t2">${k}</div></td>${DB.roles.map(r => `<td><input type="checkbox" data-p="${k}" data-r="${r.id}" ${r.perms.includes(k) ? 'checked' : ''} ${r.id === 'r-admin' ? 'disabled' : ''} style="width:17px;height:17px;accent-color:var(--primary)"></td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
  $('#addr', el).onclick = () => editRole();
  $$('[data-re]', el).forEach(b => b.onclick = () => editRole(roleById(b.dataset.re)));
  $$('[data-rd]', el).forEach(b => b.onclick = async () => { const r = roleById(b.dataset.rd); const n = DB.users.filter(u => u.roleId === r.id).length; if (n) { toast(`Cannot delete – ${n} user(s) have this role.`, true); return; } if (await confirmBox('Delete role', `Delete role <b>${esc(r.name)}</b>?`, 'Delete', true)) { DB.roles = DB.roles.filter(x => x.id !== r.id); audit('Roles', 'Role Deleted', `Role '${r.name}' deleted.`); saveDB(); rerender(); } });
  $$('[data-p]', el).forEach(c => c.onchange = () => { const r = roleById(c.dataset.r); if (c.checked) r.perms.push(c.dataset.p); else r.perms = r.perms.filter(p => p !== c.dataset.p); audit('Roles', 'Role Updated', `Role '${r.name}' permission '${c.dataset.p}' ${c.checked ? 'granted' : 'revoked'}.`); saveDB(); toast('Permissions updated.'); renderSidebar(); });
};

// ----- Departments -----
ADMIN.departments = (el) => {
  const edit = (d) => formModal({ title: d ? 'Edit Department' : 'Add Department', fields: [{ name: 'name', label: 'Department Name', required: true, value: d?.name }, { name: 'code', label: 'Code (used in memo numbers)', required: true, value: d?.code, hint: 'Short code, e.g. ICT, HR, FIN' }, { name: 'division', label: 'Division / Business Unit', value: d?.division || 'Corporate Division' }, { name: 'head', label: 'Department Head', type: 'select', options: [['', '— None —'], ...DB.users.map(u => [u.id, u.name])], value: d?.head || '' }, { name: 'status', label: 'Status', type: 'select', options: ['Active', 'Inactive'], value: d?.status || 'Active' }], onSave: v => { v.code = v.code.toUpperCase().replace(/[^A-Z0-9]/g, ''); if (DB.departments.some(x => x.code === v.code && x.id !== d?.id)) { toast('Code already used.', true); return false; } if (d) Object.assign(d, v); else DB.departments.push({ id: uid('d'), ...v, createdAt: iso(NOW()) }); audit('Departments', d ? 'Department Updated' : 'Department Created', `Department '${v.name}' saved.`); saveDB(); toast('Department saved.'); rerender(); } });
  const t = dataTable({ id: 'depts', rows: DB.departments, columns: [{ key: 'name', label: 'Department', render: d => `<span class="row"><span class="cat-ic" style="background:var(--primary);width:30px;height:30px">${icon('building')}</span><b class="small">${esc(d.name)}</b></span>` }, { key: 'code', label: 'Code' }, { key: 'division', label: 'Division / BU' }, { key: 'head', label: 'Department Head', render: d => d.head ? esc(userById(d.head).name) : '<span class="t2">—</span>', sortVal: d => userById(d.head).name }, { key: 'users', label: 'Users', render: d => DB.users.filter(u => u.deptId === d.id).length, sortVal: d => DB.users.filter(u => u.deptId === d.id).length }, { key: 'memos', label: 'Memos Issued', render: d => DB.memos.filter(m => m.deptId === d.id && m.releasedAt).length, sortVal: d => DB.memos.filter(m => m.deptId === d.id).length }, { key: 'status', label: 'Status', render: d => badge(d.status) }, { label: 'Actions', render: d => `<button class="icon-btn" data-de="${d.id}">${icon('edit')}</button><button class="icon-btn" data-dd="${d.id}">${icon('trash')}</button>` }] });
  el.innerHTML = `<div class="row mb" style="justify-content:flex-end"><button class="btn primary" id="addd">${icon('plus')} Add Department</button></div><div class="grid g4 mb">${statCard('blue', 'building', 'Departments', DB.departments.length, 'Total')}${statCard('green', 'checkc', 'Active', DB.departments.filter(d => d.status === 'Active').length, 'Departments')}${statCard('purple', 'users', 'Divisions / BUs', new Set(DB.departments.map(d => d.division)).size, 'Groups')}${statCard('orange', 'user', 'Without Head', DB.departments.filter(d => !d.head).length, 'Need assignment')}</div><div class="card">${t.html}</div>`;
  t.mount(el, rerender);
  $('#addd', el).onclick = () => edit();
  $$('[data-de]', el).forEach(b => b.onclick = () => edit(DB.departments.find(d => d.id === b.dataset.de)));
  $$('[data-dd]', el).forEach(b => b.onclick = async () => { const d = DB.departments.find(x => x.id === b.dataset.dd); const n = DB.users.filter(u => u.deptId === d.id).length + DB.memos.filter(m => m.deptId === d.id).length; if (n) { toast('Cannot delete – department has users or memos. Set it to Inactive instead.', true); return; } if (await confirmBox('Delete department', `Delete <b>${esc(d.name)}</b>?`, 'Delete', true)) { DB.departments = DB.departments.filter(x => x.id !== d.id); audit('Departments', 'Department Deleted', `Department '${d.name}' deleted.`); saveDB(); rerender(); } });
};

// ----- Workflows -----
ADMIN.workflows = (el) => {
  const approvers = DB.users.filter(u => roleById(u.roleId).perms.includes('memo.approve'));
  const edit = (w) => {
    const steps = w ? JSON.parse(JSON.stringify(w.steps)) : [{ label: 'Initial Approver', userId: approvers[0]?.id, slaDays: 2 }, { label: 'Final Approver', userId: approvers[1]?.id, slaDays: 1 }];
    const stepsHTML = () => steps.map((s, i) => `<div class="row" style="gap:8px;margin-bottom:8px"><span class="pill-count" style="border-radius:50%;width:24px;height:24px">${i + 1}</span><input class="inp" style="flex:1" data-sl="${i}" value="${esc(s.label)}"><select class="inp" style="flex:1.4" data-su="${i}">${selectOpts(approvers.map(a => [a.id, a.name + ' (' + a.title + ')']), s.userId)}</select><input class="inp" type="number" min="0.5" step="0.5" style="width:80px" data-sd="${i}" value="${s.slaDays}" title="SLA days"><button class="icon-btn" data-up="${i}" title="Move up">↑</button><button class="icon-btn" data-sx="${i}">${icon('trash')}</button></div>`).join('');
    modal({ title: w ? 'Edit Workflow' : 'New Workflow', wide: true, body: `<div class="grid g2"><div class="field"><label>Workflow Name <span class="req">*</span></label><input class="inp" id="w-name" value="${esc(w?.name || '')}"></div><div class="field"><label>Escalate overdue approvals to</label><select class="inp" id="w-esc">${selectOpts(approvers.map(a => [a.id, a.name]), w?.escalateTo)}</select></div><div class="field" style="grid-column:1/-1"><label>Description</label><input class="inp" id="w-desc" value="${esc(w?.description || '')}"></div></div><div><div class="row small bold" style="gap:8px;margin-bottom:6px"><span style="width:24px"></span><span style="flex:1">Step label</span><span style="flex:1.4">Approver</span><span style="width:80px">SLA (days)</span><span style="width:70px"></span></div><div id="w-steps">${stepsHTML()}</div><button class="btn sm" id="w-add">${icon('plus')} Add Step</button></div>`, foot: `<button class="btn" data-x>Cancel</button><button class="btn primary" id="w-save">Save Workflow</button>`, onMount: (m, close) => {
      const sync = () => { $$('[data-sl]', m).forEach(i => steps[+i.dataset.sl].label = i.value); $$('[data-su]', m).forEach(i => steps[+i.dataset.su].userId = i.value); $$('[data-sd]', m).forEach(i => steps[+i.dataset.sd].slaDays = +i.value || 1); };
      const redraw = () => { $('#w-steps', m).innerHTML = stepsHTML(); wire(); };
      const wire = () => { $$('[data-sx]', m).forEach(b => b.onclick = () => { sync(); if (steps.length === 1) { toast('A workflow needs at least one step.', true); return; } steps.splice(+b.dataset.sx, 1); redraw(); }); $$('[data-up]', m).forEach(b => b.onclick = () => { sync(); const i = +b.dataset.up; if (i > 0) { [steps[i - 1], steps[i]] = [steps[i], steps[i - 1]]; redraw(); } }); };
      wire(); $('#w-add', m).onclick = () => { sync(); steps.push({ label: 'Approver', userId: approvers[0]?.id, slaDays: 2 }); redraw(); };
      $('#w-save', m).onclick = () => { sync(); const name = $('#w-name', m).value.trim(); if (!name) { toast('Name is required.', true); return; } const data = { name, description: $('#w-desc', m).value.trim(), escalateTo: $('#w-esc', m).value, steps }; if (w) Object.assign(w, data); else DB.workflows.push({ id: uid('wf'), status: 'Active', ...data }); audit('Workflow', w ? 'Workflow Updated' : 'Workflow Created', `Workflow '${name}' saved with ${steps.length} step(s).`); saveDB(); close(); toast('Workflow saved.'); rerender(); };
    } });
  };
  el.innerHTML = `<div class="row mb"><div class="info" style="flex:1">${icon('info')}<div>Workflows define who approves a memo and in what order. Each step has an SLA (days allowed). Authors choose a workflow when submitting, and may change the initial approver.</div></div><button class="btn primary" id="addw">${icon('plus')} New Workflow</button></div>
  <div class="grid g2">${DB.workflows.map(w => `<div class="card card-pad"><div class="card-h"><div><h3>${esc(w.name)}</h3><div class="small t2" style="margin-top:4px">${esc(w.description)}</div></div><div class="row">${badge(w.status)}<button class="icon-btn" data-we="${w.id}">${icon('edit')}</button><button class="icon-btn" data-wm="${w.id}">${icon('dots')}</button></div></div>
    <div class="tl">${w.steps.map((s, i) => `<div class="tl-i" style="padding-bottom:12px"><div class="dotc cur">${i + 1}</div><div style="flex:1"><div class="row"><b class="small">${esc(userLabel(s.userId))}</b><span class="spacer"></span><span class="badge b-blue" style="text-transform:none">SLA: ${s.slaDays} day(s)</span></div><div class="xs t2">${esc(s.label)}</div></div></div>`).join('')}</div>
    <div class="row small t2">${icon('clock')} Total SLA: ${w.steps.reduce((a, s) => a + s.slaDays, 0)} days · Escalation: ${esc(userById(w.escalateTo).name)} · Used by ${DB.memos.filter(m => m.workflowId === w.id).length} memo(s)</div></div>`).join('')}</div>`;
  $('#addw', el).onclick = () => edit();
  $$('[data-we]', el).forEach(b => b.onclick = () => edit(wfById(b.dataset.we)));
  $$('[data-wm]', el).forEach(b => b.onclick = () => { const w = wfById(b.dataset.wm); popMenu(b, [{ label: 'Duplicate', icon: 'copy', onClick: () => { DB.workflows.push({ ...JSON.parse(JSON.stringify(w)), id: uid('wf'), name: w.name + ' (Copy)' }); saveDB(); rerender(); } }, { label: w.status === 'Active' ? 'Deactivate' : 'Activate', icon: 'refresh', onClick: () => { if (w.status === 'Active' && DB.workflows.filter(x => x.status === 'Active').length === 1) { toast('At least one workflow must stay active.', true); return; } w.status = w.status === 'Active' ? 'Inactive' : 'Active'; audit('Workflow', 'Workflow Status Changed', `${w.name} set to ${w.status}.`); saveDB(); rerender(); } }]); });
};

// ----- Memo Templates -----
ADMIN.templates = (el) => {
  const edit = (t) => {
    modal({ title: t ? 'Edit Memo Template' : 'Create Memo Template', wide: true, body: `<div class="grid g3"><div class="field"><label>Template Name <span class="req">*</span></label><input class="inp" id="tp-name" value="${esc(t?.name || '')}"></div><div class="field"><label>Memo Type</label><select class="inp" id="tp-type">${selectOpts(DB.settings.memoTypes, t?.type)}</select></div><div class="field"><label>Default Category</label><select class="inp" id="tp-cat">${selectOpts(DB.categories.map(c => [c.id, c.name]), t?.categoryId)}</select></div><div class="field" style="grid-column:1/-1"><label>Description</label><input class="inp" id="tp-desc" value="${esc(t?.description || '')}"></div></div><div class="field"><label>Template Content</label>${editorHTML(t?.content || '<p>Please be informed that ...</p>')}<div class="xs t2">Tip: use [brackets] for parts the author should replace.</div></div>`, foot: `<button class="btn" data-x>Cancel</button><button class="btn primary" id="tp-save">Save Template</button>`, onMount: (m, close) => {
      wireEditor(m);
      $('#tp-save', m).onclick = () => { const name = $('#tp-name', m).value.trim(); if (!name) { toast('Name is required.', true); return; } const data = { name, type: $('#tp-type', m).value, categoryId: $('#tp-cat', m).value, description: $('#tp-desc', m).value.trim(), content: $('#ed-area', m).innerHTML, updatedAt: iso(NOW()) }; if (t) Object.assign(t, data); else DB.templates.push({ id: uid('t'), status: 'Active', ...data }); audit('Templates', t ? 'Template Updated' : 'Template Created', `Memo template '${name}' saved.`); saveDB(); close(); toast('Template saved.'); rerender(); };
    } });
  };
  const t = dataTable({ id: 'tpls', rows: DB.templates, columns: [{ key: 'name', label: 'Template Name', render: x => `<span class="row"><span class="cat-ic" style="background:var(--purple);width:30px;height:30px">${icon('template')}</span><b class="small">${esc(x.name)}</b></span>` }, { key: 'type', label: 'Memo Type' }, { key: 'cat', label: 'Category', render: x => esc(catById(x.categoryId).name), sortVal: x => catById(x.categoryId).name }, { key: 'description', label: 'Description', render: x => `<span class="small t2">${esc(x.description)}</span>` }, { key: 'updatedAt', label: 'Last Updated', render: x => fmtDate(x.updatedAt) }, { key: 'status', label: 'Status', render: x => badge(x.status) }, { label: 'Actions', render: x => `<span class="row" style="gap:2px"><button class="icon-btn" title="Preview" data-tv="${x.id}">${icon('eye')}</button><button class="icon-btn" data-te="${x.id}">${icon('edit')}</button><button class="icon-btn" data-tm="${x.id}">${icon('dots')}</button></span>` }] });
  el.innerHTML = `<div class="row mb" style="justify-content:flex-end"><button class="btn primary" id="addt">${icon('plus')} Create Template</button></div><div class="grid g4 mb">${statCard('purple', 'template', 'Total Templates', DB.templates.length, 'Available')}${statCard('green', 'checkc', 'Active', DB.templates.filter(x => x.status === 'Active').length, 'Shown in Create Memo')}${statCard('blue', 'memo', 'Memo Types', DB.settings.memoTypes.length, 'Configured')}${statCard('orange', 'calendar', 'Last Updated', `<span style="font-size:18px">${fmtDate(DB.templates.slice().sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))[0]?.updatedAt)}</span>`, '')}</div><div class="card">${t.html}</div>`;
  t.mount(el, rerender);
  $('#addt', el).onclick = () => edit();
  $$('[data-te]', el).forEach(b => b.onclick = () => edit(DB.templates.find(x => x.id === b.dataset.te)));
  $$('[data-tv]', el).forEach(b => b.onclick = () => { const x = DB.templates.find(y => y.id === b.dataset.tv); modal({ title: x.name, wide: true, body: memoDocHTML({ no: 'LGC-XXX-MM-0000-000', subject: '[Subject]', to: ['all'], cc: [], deptId: me().deptId, createdBy: DB.currentUserId, effectiveDate: toInputDate(NOW().toISOString()), content: x.content, attachments: [] }) }); });
  $$('[data-tm]', el).forEach(b => b.onclick = () => { const x = DB.templates.find(y => y.id === b.dataset.tm); popMenu(b, [{ label: 'Use Template', icon: 'plus', onClick: () => location.hash = '#/create?template=' + x.id }, { label: 'Duplicate', icon: 'copy', onClick: () => { DB.templates.push({ ...x, id: uid('t'), name: x.name + ' (Copy)', updatedAt: iso(NOW()) }); saveDB(); rerender(); } }, { label: x.status === 'Active' ? 'Deactivate' : 'Activate', icon: 'refresh', onClick: () => { x.status = x.status === 'Active' ? 'Inactive' : 'Active'; saveDB(); rerender(); } }, '-', { label: 'Delete', icon: 'trash', danger: true, onClick: async () => { if (await confirmBox('Delete template', `Delete <b>${esc(x.name)}</b>?`, 'Delete', true)) { DB.templates = DB.templates.filter(y => y.id !== x.id); audit('Templates', 'Template Deleted', `Template '${x.name}' deleted.`); saveDB(); rerender(); } } }]); });
};

// ----- Notification Templates -----
ADMIN.notifications = (el) => {
  const vars = ['{{recipient}}', '{{memo_no}}', '{{subject}}', '{{approver}}', '{{due_date}}', '{{effective_date}}', '{{ack_due}}', '{{comments}}'];
  const edit = (n) => modal({ title: 'Edit Notification Template', wide: true, body: `<div class="grid g2"><div class="field"><label>Event</label><input class="inp" value="${esc(n.event)}" disabled></div><div class="field"><label>Channel</label><select class="inp" id="nt-ch">${selectOpts(['Email', 'In-System', 'Email & In-System', 'Email, In-System & Teams'], n.channel)}</select></div></div><div class="field"><label>Subject</label><input class="inp" id="nt-sub" value="${esc(n.subject)}"></div><div class="field"><label>Message Body</label><textarea class="inp" id="nt-body" rows="9">${esc(n.body)}</textarea></div><div class="small t2">Available placeholders (click to insert): ${vars.map(v => `<button class="btn sm" data-var="${v}" style="margin:2px">${v}</button>`).join('')}</div><div class="field"><label>Preview</label><div class="card card-pad" id="nt-prev" style="white-space:pre-wrap;background:#fafbfd"></div></div><label class="check"><input type="checkbox" id="nt-act" ${n.status === 'Active' ? 'checked' : ''}> Active</label>`, foot: `<button class="btn" data-x>Cancel</button><button class="btn primary" id="nt-save">Save Template</button>`, onMount: (m, close) => {
    const sample = { recipient: me().name, memo_no: 'LGC-ICT-MM-2026-015', subject: 'Implementation of MFA', approver: 'Noe Garcia', due_date: fmtDate(new Date(Date.now() + 2 * DAY).toISOString()), effective_date: fmtDate(NOW().toISOString()), ack_due: fmtDate(new Date(Date.now() + 5 * DAY).toISOString()), comments: 'Please revise section 2.' };
    const fill = s => s.replace(/\{\{(\w+)\}\}/g, (_, k) => sample[k] ?? '');
    const prev = () => $('#nt-prev', m).textContent = 'Subject: ' + fill($('#nt-sub', m).value) + '\n\n' + fill($('#nt-body', m).value);
    prev(); $('#nt-sub', m).oninput = prev; $('#nt-body', m).oninput = prev;
    let last = $('#nt-body', m); $('#nt-sub', m).onfocus = e => last = e.target; $('#nt-body', m).onfocus = e => last = e.target;
    $$('[data-var]', m).forEach(b => b.onclick = () => { const s = last.selectionStart ?? last.value.length; last.value = last.value.slice(0, s) + b.dataset.var + last.value.slice(last.selectionEnd ?? s); prev(); last.focus(); });
    $('#nt-save', m).onclick = () => { Object.assign(n, { channel: $('#nt-ch', m).value, subject: $('#nt-sub', m).value, body: $('#nt-body', m).value, status: $('#nt-act', m).checked ? 'Active' : 'Inactive', updatedAt: iso(NOW()) }); audit('Notifications', 'Template Updated', `Notification template '${n.event}' updated.`); saveDB(); close(); toast('Notification template saved.'); rerender(); };
  } });
  el.innerHTML = `<div class="info mb">${icon('info')}<div>These messages are sent automatically when memo events happen. In this prototype, emails are simulated – notifications appear in the bell icon of each user.</div></div><div class="card"><table class="tbl"><thead><tr><th>Event</th><th>Channel</th><th>Subject</th><th>Last Updated</th><th>Status</th><th>Actions</th></tr></thead><tbody>${DB.notifTemplates.map(n => `<tr><td><span class="row"><span class="cat-ic" style="background:var(--teal);width:30px;height:30px">${icon('mail')}</span><b class="small">${esc(n.event)}</b></span></td><td>${esc(n.channel)}</td><td class="small">${esc(n.subject)}</td><td>${fmtDate(n.updatedAt)}</td><td>${badge(n.status)}</td><td><button class="btn sm" data-ne="${n.id}">${icon('edit')} Edit</button></td></tr>`).join('')}</tbody></table></div>`;
  $$('[data-ne]', el).forEach(b => b.onclick = () => edit(DB.notifTemplates.find(n => n.id === b.dataset.ne)));
};

// ----- Configuration (lists) -----
ADMIN.configuration = (el) => {
  const S = DB.settings;
  const listCard = (key, title, desc) => `<div class="card card-pad"><div class="card-h"><div><h3>${title}</h3><div class="small t2" style="margin-top:4px">${desc}</div></div></div>${S[key].map((v, i) => `<div class="file-row"><span style="flex:1">${esc(v)}</span><button class="icon-btn" data-lu="${key}:${i}">↑</button><button class="icon-btn" data-lx="${key}:${i}">${icon('trash')}</button></div>`).join('')}<div class="row mt"><input class="inp" placeholder="Add new…" id="add-${key}"><button class="btn" data-la="${key}">${icon('plus')} Add</button></div></div>`;
  el.innerHTML = `<div class="grid g3 mb">${listCard('memoTypes', 'Memo Types', 'Types available when creating a memo.')}${listCard('priorities', 'Priority Levels', 'Priority options for memos.')}${listCard('confidentiality', 'Confidentiality Levels', 'Classification of memo content.')}</div>
  <div class="card card-pad"><h3 class="mb">Memo Numbering</h3><div class="grid g3"><div class="field"><label>Number Format</label><input class="inp" id="cf-fmt" value="${esc(S.numberFormat)}"><div class="xs t2">Placeholders: {DEPT}, {YEAR}, {MM}, {SEQ}</div></div><div class="field"><label>Preview</label><div class="inp" id="cf-prev" style="background:#f6f7fa"></div></div><div class="field"><label>&nbsp;</label><button class="btn primary" id="cf-save">${icon('save')} Save Format</button></div></div></div>`;
  const prev = () => $('#cf-prev', el).textContent = $('#cf-fmt', el).value.replace('{DEPT}', 'ICT').replace('{YEAR}', NOW().getFullYear()).replace('{MM}', String(NOW().getMonth() + 1).padStart(2, '0')).replace('{SEQ}', '016');
  prev(); $('#cf-fmt', el).oninput = prev;
  $('#cf-save', el).onclick = () => { const v = $('#cf-fmt', el).value.trim(); if (!v.includes('{SEQ}')) { toast('Format must include {SEQ}.', true); return; } S.numberFormat = v; audit('Configuration', 'Numbering Format Changed', 'Memo number format set to ' + v); saveDB(); toast('Numbering format saved. Applies to new memos.'); };
  $$('[data-la]', el).forEach(b => b.onclick = () => { const k = b.dataset.la; const i = $('#add-' + k, el); const v = i.value.trim(); if (!v || S[k].includes(v)) return; S[k].push(v); audit('Configuration', 'List Updated', `Added '${v}' to ${k}.`); saveDB(); rerender(); });
  $$('[data-lx]', el).forEach(b => b.onclick = () => { const [k, i] = b.dataset.lx.split(':'); if (S[k].length <= 1) return; S[k].splice(+i, 1); saveDB(); rerender(); });
  $$('[data-lu]', el).forEach(b => b.onclick = () => { const [k, i] = b.dataset.lu.split(':'); const n = +i; if (n > 0) { [S[k][n - 1], S[k][n]] = [S[k][n], S[k][n - 1]]; saveDB(); rerender(); } });
};

// ----- Audit Logs -----
ADMIN.audit = (el) => {
  const q = AF.q.toLowerCase();
  const rows = DB.audit.filter(a => (!q || `${a.action} ${a.details}`.toLowerCase().includes(q)) && (!AF.module || a.module === AF.module) && (!AF.user || a.userId === AF.user) && (!AF.from || a.date.slice(0, 10) >= AF.from) && (!AF.to || a.date.slice(0, 10) <= AF.to));
  const modules = [...new Set(DB.audit.map(a => a.module))].sort();
  const today = DB.audit.filter(a => new Date(a.date).toDateString() === new Date().toDateString()).length;
  const t = dataTable({ id: 'audit', rows, defaultSort: 'date', defaultDir: 'desc', columns: [{ key: 'date', label: 'Date & Time', render: a => fmtDT(a.date) }, { key: 'user', label: 'User', render: a => `<span class="row">${avatar(a.userId, 'sm')}${esc(userById(a.userId).name)}</span>`, sortVal: a => userById(a.userId).name }, { key: 'module', label: 'Module', render: a => badge(a.module, 'b-blue') }, { key: 'action', label: 'Action', render: a => `<b class="small">${esc(a.action)}</b>` }, { key: 'details', label: 'Details', render: a => `<span class="small">${esc(a.details)}</span>` }, { key: 'ip', label: 'IP Address', render: a => `<span class="xs t2">${esc(a.ip || '')}</span>` }] });
  el.innerHTML = `<div class="grid g4 mb">${statCard('blue', 'activity', 'Total Log Entries', DB.audit.length.toLocaleString(), 'All recorded events')}${statCard('green', 'calendar', 'Today', today, 'Events today')}${statCard('orange', 'user', 'Logins', DB.audit.filter(a => a.action === 'User Login').length, 'All time')}${statCard('purple', 'memo', 'Memo Events', DB.audit.filter(a => a.module === 'Memo' || a.module === 'Approval').length, 'Create / approve / release')}</div>
  <div class="card"><div class="filters"><div class="field search"><input class="inp" id="a-q" placeholder="Search activity or details..." value="${esc(AF.q)}">${icon('search')}</div><div class="field"><label>Module</label><select class="inp" id="a-module">${selectOpts(modules, AF.module, 'All Modules')}</select></div><div class="field"><label>User</label><select class="inp" id="a-user">${selectOpts(DB.users.map(u => [u.id, u.name]), AF.user, 'All Users')}</select></div><div class="field" style="flex:0 1 150px"><label>From</label><input type="date" class="inp" id="a-from" value="${AF.from}"></div><div class="field" style="flex:0 1 150px"><label>To</label><input type="date" class="inp" id="a-to" value="${AF.to}"></div><button class="btn" id="a-reset">${icon('reset')} Reset</button><button class="btn" id="a-exp">${icon('download')} Export</button></div>${t.html}</div>`;
  t.mount(el, rerender);
  let tm; $('#a-q', el).oninput = e => { clearTimeout(tm); tm = setTimeout(() => { AF.q = e.target.value; rerender(); const n = $('#a-q'); n.focus(); n.setSelectionRange(n.value.length, n.value.length); }, 300); };
  ['module', 'user', 'from', 'to'].forEach(k => $('#a-' + k, el).onchange = e => { AF[k] = e.target.value; TableState.audit.page = 1; rerender(); });
  $('#a-reset', el).onclick = () => { Object.assign(AF, { q: '', module: '', user: '', from: '', to: '' }); rerender(); };
  $('#a-exp', el).onclick = () => exportCSV('audit-log.csv', ['Date', 'User', 'Module', 'Action', 'Details', 'IP'], rows.map(a => [fmtDT(a.date), userById(a.userId).name, a.module, a.action, a.details, a.ip]));
};

// ----- System Settings -----
ADMIN.settings = (el) => {
  const S = DB.settings;
  const f = (k, l, type = 'text', extra = '') => `<div class="field"><label>${l}</label>${type === 'checkbox' ? `<label class="check"><input type="checkbox" data-s="${k}" ${S[k] ? 'checked' : ''}> Enabled</label>` : `<input class="inp" type="${type}" data-s="${k}" value="${esc(S[k])}" ${extra}>`}</div>`;
  el.innerHTML = `<div class="grid g2">
    <div class="card card-pad"><h3 class="mb">General</h3><div class="grid g2">${f('orgName', 'Organization Name')}${f('systemName', 'System Short Name')}${f('systemFullName', 'System Full Name')}${f('timezone', 'Time Zone')}</div><div class="mt">${f('footerNote', 'Dashboard Footer Note')}</div></div>
    <div class="card card-pad"><h3 class="mb">Memo Defaults</h3><div class="grid g2">${f('defaultAckDays', 'Default Acknowledgement Due (days)', 'number', 'min="1"')}${f('defaultSlaDays', 'Default Approval SLA (days)', 'number', 'min="1"')}<div class="field"><label>Default Priority</label><select class="inp" data-s="defaultPriority">${selectOpts(S.priorities, S.defaultPriority)}</select></div>${f('maxUploadMB', 'Max Upload Size (MB)', 'number', 'min="1"')}</div><div class="mt">${f('allowedFiles', 'Allowed File Types')}</div></div>
    <div class="card card-pad"><h3 class="mb">Security</h3><div class="grid g2">${f('sessionTimeout', 'Session Timeout (minutes)', 'number')}${f('passwordMinLength', 'Minimum Password Length', 'number')}</div></div>
    <div class="card card-pad"><h3 class="mb">Notifications & Records</h3><div class="grid g2">${f('emailEnabled', 'Email Notifications', 'checkbox')}${f('teamsEnabled', 'Microsoft Teams Notifications', 'checkbox')}${f('retentionYears', 'Record Retention (years)', 'number')}${f('autoArchiveExpired', 'Auto-archive Expired Memos', 'checkbox')}</div></div>
  </div><div class="row mt" style="justify-content:flex-end"><button class="btn primary lg" id="st-save">${icon('save')} Save Settings</button></div>`;
  $('#st-save', el).onclick = () => { $$('[data-s]', el).forEach(i => { const k = i.dataset.s; S[k] = i.type === 'checkbox' ? i.checked : i.type === 'number' ? +i.value : i.value; }); audit('Settings', 'Settings Updated', 'System settings were updated.'); saveDB(); toast('Settings saved.'); render(); };
};

// ----- Backup & Recovery -----
ADMIN.backup = (el) => {
  el.innerHTML = `<div class="grid g3 mb">${statCard('blue', 'database', 'Data Size', fmtSize(storageSize()), 'Memo database')}${statCard('green', 'checkc', 'Last Backup', `<span style="font-size:18px">${DB.backups[0] ? fmtDT(DB.backups[0].date) : 'Never'}</span>`, DB.backups[0]?.type || '')}${statCard('purple', 'memo', 'Records', (DB.memos.length + DB.users.length + DB.audit.length).toLocaleString(), 'Memos, users & logs')}</div>
  <div class="grid g3 mb">
    <div class="card card-pad"><h3 class="mb">${icon('download')} Create Backup</h3><p class="t2 small">Download a complete copy of all memos, users, settings and logs as a file. Keep it somewhere safe (e.g. OneDrive).</p><button class="btn primary" id="bk-dl">${icon('download')} Download Backup Now</button></div>
    <div class="card card-pad"><h3 class="mb">${icon('upload')} Restore from Backup</h3><p class="t2 small">Replace all current data with a previously downloaded backup file (.json).</p><button class="btn warn" id="bk-up">${icon('upload')} Restore Backup File</button><input type="file" id="bk-file" accept=".json" hidden></div>
    <div class="card card-pad"><h3 class="mb">${icon('reset')} Reset Demo Data</h3><p class="t2 small">Erase everything and reload the original sample data. Useful after testing.</p><button class="btn danger" id="bk-reset">${icon('trash')} Reset to Sample Data</button></div>
  </div>
  <div class="card"><div class="card-pad" style="padding-bottom:6px"><h3>Backup History</h3></div><table class="tbl"><thead><tr><th>Date & Time</th><th>Type</th><th>Size</th><th>Performed By</th><th>Status</th></tr></thead><tbody>${DB.backups.map(b => `<tr><td>${fmtDT(b.date)}</td><td>${esc(b.type)}</td><td>${esc(b.size)}</td><td>${esc(userById(b.by).name)}</td><td>${badge(b.status)}</td></tr>`).join('')}</tbody></table></div>
  <div class="info mt">${icon('info')}<div>Attachment files are stored separately in the browser and are <b>not</b> included in the backup file in this prototype.</div></div>`;
  $('#bk-dl', el).onclick = () => { const data = JSON.stringify(DB); DB.backups.unshift({ id: uid('b'), date: iso(NOW()), type: 'Manual', size: fmtSize(data.length), by: DB.currentUserId, status: 'Completed' }); audit('Backup', 'Backup Completed', 'Manual backup downloaded.'); saveDB(); const d = new Date(); downloadBlob(new Blob([JSON.stringify(DB, null, 1)], { type: 'application/json' }), `emms-backup-${toInputDate(d.toISOString())}.json`); toast('Backup downloaded.'); rerender(); };
  $('#bk-up', el).onclick = () => $('#bk-file', el).click();
  $('#bk-file', el).onchange = async e => { const f = e.target.files[0]; if (!f) return; try { const d = JSON.parse(await f.text()); if (!d.memos || !d.users || !d.settings) throw new Error('Not an EMMS backup'); if (!await confirmBox('Restore backup', `Replace ALL current data with <b>${esc(f.name)}</b>? This cannot be undone.`, 'Restore', true)) return; const keepUser = DB.currentUserId; DB = d; if (!DB.users.find(u => u.id === keepUser)) DB.currentUserId = DB.users[0].id; audit('Backup', 'Backup Restored', `Data restored from ${f.name}.`); saveDB(); toast('Backup restored.'); location.hash = '#/dashboard'; render(); } catch (err) { toast('Invalid backup file: ' + err.message, true); } };
  $('#bk-reset', el).onclick = async () => { if (await confirmBox('Reset data', 'This will <b>erase all data</b> (memos, users, settings) and reload the sample data. Download a backup first if you want to keep anything. Continue?', 'Reset Everything', true)) { resetDB(); toast('Sample data restored.'); location.hash = '#/dashboard'; render(); } };
};

// ----- Archive & Records -----
ADMIN.archive = (el) => {
  const ret = DB.settings.retentionYears;
  const expired = DB.memos.filter(m => memoStatus(m) === 'Expired');
  const archived = DB.memos.filter(m => m.status === 'Archived');
  const superseded = DB.memos.filter(m => m.status === 'Superseded');
  const dueDisposal = archived.filter(m => new Date(m.releasedAt || m.createdAt) < new Date(Date.now() - ret * 365 * DAY));
  let tab = CUR.query.tab || 'archived';
  const lists = { archived, superseded, expired, disposal: dueDisposal };
  const t = dataTable({ id: 'arch', rows: lists[tab], columns: [{ key: 'no', label: 'Memo No.', render: pdfCell }, { key: 'subject', label: 'Title', render: m => esc(m.subject) }, { key: 'cat', label: 'Category', render: m => esc(catById(m.categoryId).name), sortVal: m => catById(m.categoryId).name }, { key: 'releasedAt', label: 'Released', render: m => fmtDate(m.releasedAt) }, { key: 'archivedAt', label: tab === 'archived' ? 'Archived On' : 'Status', render: m => tab === 'archived' ? fmtDate(m.archivedAt) : badge(memoStatus(m)) }, { key: 'ret', label: 'Retain Until', render: m => fmtDate(new Date(new Date(m.releasedAt || m.createdAt).getTime() + ret * 365 * DAY).toISOString()), sort: false }, { label: 'Actions', render: m => `<span class="row" style="gap:4px">${m.status !== 'Archived' ? `<button class="btn sm" data-arc="${m.id}">${icon('archive')} Archive</button>` : `<button class="btn sm" data-res="${m.id}">${icon('refresh')} Restore</button>`}<a class="icon-btn" href="#/memo/${m.id}">${icon('eye')}</a></span>` }] });
  el.innerHTML = `<div class="grid g4 mb">${statCard('purple', 'archive', 'Archived', archived.length, 'Memos in archive')}${statCard('orange', 'copy', 'Superseded', superseded.length, 'Replaced by newer versions')}${statCard('red', 'calendar', 'Expired (Active)', expired.length, 'Past expiry date')}${statCard('gray', 'trash', 'Due for Disposal Review', dueDisposal.length, `Older than ${ret} years`)}</div>
  <div class="card"><div class="card-pad row" style="padding-bottom:0"><div style="flex:1"><h3>Archive & Records Management</h3><div class="small t2" style="margin-top:4px">Retention period: <b>${ret} years</b> (change in System Settings).</div></div>${expired.length || superseded.length ? `<button class="btn primary" id="arc-all">${icon('archive')} Archive All Expired & Superseded</button>` : ''}</div>
  <div class="tabs mt">${[['archived', 'Archived'], ['superseded', 'Superseded'], ['expired', 'Expired'], ['disposal', 'Due for Disposal Review']].map(([k, l]) => `<a class="tab ${tab === k ? 'active' : ''}" href="#/admin/archive?tab=${k}" style="text-decoration:none">${l} (${lists[k].length})</a>`).join('')}</div>${t.html}</div>`;
  t.mount(el, rerender);
  $$('[data-arc]', el).forEach(b => b.onclick = () => { MemoActions.setStatus(memoById(b.dataset.arc), 'Archived', 'Archived from Records Management'); toast('Memo archived.'); rerender(); });
  $$('[data-res]', el).forEach(b => b.onclick = () => { MemoActions.setStatus(memoById(b.dataset.res), 'Active', 'Restored from archive'); toast('Memo restored.'); rerender(); });
  const aa = $('#arc-all', el); if (aa) aa.onclick = async () => { const list = [...expired, ...superseded]; if (await confirmBox('Archive memos', `Archive ${list.length} expired and superseded memo(s)?`, 'Archive All')) { list.forEach(m => MemoActions.setStatus(m, 'Archived', 'Bulk archive')); toast(`${list.length} memo(s) archived.`); rerender(); } };
};
